  // munge of OP_listColumns.sen

  sFileContents =
    "\""
    "\\\"munged OP_listColumns.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_listColumns.sen -- Operator list columns                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_listColumns.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lscol_action\n"
    "\n"
    "  0 locals| iColumns |\n"
    "\n"
    "  // find the table\n"
    "  <tableNm> op__table not if\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // get the table column count\n"
    "  table[].columnCount@ to iColumns\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeout\n"
    "\n"
    "  // create an infoSet operand\n"
    "  streamSetTable[] StreamSet[].new\n"
    "\n"
    "  // insert a row in the infoset for each column\n"
    "  iColumns 0 do\n"
    "    I table[].column@\n"
    "    streamSetTable[] StreamSet[].addColumnDef not if\n"
    "      StreamSet[].pipeout\n"
    "      streamSetTable[] streamSet[].new\n"
    "      I table[].column@\n"
    "      streamSetTable[] StreamSet[].addColumnDef assert\n"
    "    then\n"
    "  loop\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: lscol :: lscol <tableNm> ;\n"
    "\n"
    ": lscol opInfo tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <jobDesc>     = \\\"--description of operator--\\\"\n"
    "    <localLiteOp> = true\n"
    "    <streamDef>   = __listColumns\n"
    "    <params>      = 1\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\""
  " CONSTANT OP_listColumns.sen"_Stz
  ;

