  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_fetch.sen

  sFileContents =
    "\""
    "\\\"munged OP_fetch.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_fetch.sen -- Operator fetch                                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_fetch.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate plan for the fetch                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": generatePlan ( -- )\n"
    "\n"
    "  0 locals| sPredicate |\n"
    "\n"
    "  //sWhere \\\"generatePlan\\\" \\\"%v %v\\\" str.format .\n"
    "\n"
    "  ( cdt_0 ) planner[].new\n"
    "  ( cdt_1 ) table[] Planner[].table!\n"
    "\n"
    "  ( cdt_2 ) <predicate> Planner[].parseWhere  //\\\"parseWheres\\\" .\n"
    "\n"
    "  ( cdt_3 ) Planner[].genPaths           //\\\"genPaths\\\" .\n"
    "  ( cdt_4 ) Planner[].scorePaths         //\\\"scorePaths\\\" .\n"
    "  //( cdt_5 ) Planner[].showPaths\n"
    "\n"
    "  ( cdt_6 ) Planner[].matchPaths         //\\\"matchPaths\\\" .\n"
    "  //( cdt_6 ) Planner[].showPaths\n"
    "\n"
    "  ( cdt_7 ) Planner[].choosePaths        //\\\"choosePaths\\\" .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position and begin fetch                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": positionBeginFetch ( \\\"lowerKey\\\" \\\"upperKey\\\" )\n"
    "\n"
    "  params| upperKey lowerKey |\n"
    "  0 locals| sIndexNm |\n"
    "\n"
    "  // find the index\n"
    "  0 planner[].indexNm@ to sIndexNm\n"
    "  <tableNm> sIndexNm op__index assert\n"
    "\n"
    "  // grab the table ptn read lock\n"
    "  tablePtn[].get tablePtnGrabRead2\n"
    "\n"
    "  // position in the index\n"
    "  lowerKey upperKey\n"
    "  planner[] tablePtn[].get index[].position\n"
    "\n"
    "  // fetch next buffer\n"
    "  tablePtn[].get index[].fetchNext\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CANCELMARKER ...                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchOP_CancelMarker \\\\handler\n"
    "\n"
    "  //\\\"ZK_CANCELMARKER_handler\\\" .verbose\n"
    "  nullptr to Operand[]\n"
    "  Pipein[].pipeOut\n"
    "  Op.ackPipelineJob\n"
    "\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_CRWBUFFER ...                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchOP_CrwBuffer \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_CRWBUFFER\\\" .verbose\n"
    "\n"
    "  /*\n"
    "   begin\n"
    "     Operand[].isNull\n"
    "   not while\n"
    "     Operand[].pipeout\n"
    "     tablePtn[].get index[].fetchNext to Operand[]\n"
    "   repeat\n"
    "   */\n"
    "\n"
    "  // pipeout the Operand\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // get the fetchTechnique\n"
    "  0 planner[].fetchTechnique@\n"
    "  case\n"
    "    AT_SCAN of\n"
    "      Subset[].nextBuffer to Operand[]\n"
    "    endof\n"
    "\n"
    "    // all other types of fetches, just fetchNext\n"
    "    tablePtn[].get index[].fetchNext to Operand[]\n"
    "\n"
    "  endcase\n"
    "\n"
    "  // no more data ?\n"
    "  Operand[].isNull if\n"
    "    tablePtn[].get tablePtnDropRead2\n"
    "    Operand[].newEosMarker\n"
    "    Operand[].pipeOut\n"
    "  then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_PULSEMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchOP_PulseMarker \\\\handler\n"
    "\n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  //\\\"Operand:- ZK_PULSEMARKER\\\" .verbose\n"
    "  Pipein[].pipeOut\n"
    "\n"
    "  // new a stream def\n"
    "  Operand[].newStreamDef\n"
    "  Operand[].pipeOut\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // should be one phrase\n"
    "  planner[].phrases@ to iPhrases\n"
    "  iPhrases 1 == assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the fetch technique\n"
    "  0 planner[].fetchTechnique@\n"
    "  case\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an exact select using index\n"
    "    AT_EXACT of\n"
    "     \\\"*exact*\\\" .verbose\n"
    "\n"
    "      0 planner[].key@ 0 planner[].key@\n"
    "      positionBeginFetch to Operand[]\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // lower bound select using index\n"
    "    AT_LOWER of\n"
    "      \\\"*lower*\\\" .verbose\n"
    "\n"
    "      0 planner[].lowKey@ \\\"\\\"\n"
    "      positionBeginFetch to Operand[]\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // an upper bound select using index\n"
    "    AT_UPPER of\n"
    "      \\\"*upper*\\\" .verbose\n"
    "\n"
    "      \\\"\\\" 0 planner[].upperKey@\n"
    "      positionBeginFetch to Operand[]\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // a range select using index\n"
    "    AT_RANGE of\n"
    "      \\\"*range\\\" .verbose\n"
    "\n"
    "      0 planner[].lowKey@ 0 planner[].upperKey@\n"
    "      positionBeginFetch to Operand[]\n"
    "    endof\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // full scan (no index)\n"
    "    AT_SCAN of\n"
    "      \\\"*scan*\\\" .verbose\n"
    "      // now get excat key rows from index\n"
    "      tablePtn[].get tablePtnGrabRead2\n"
    "      tablePtn[].root to Subset[]\n"
    "      Subset[]@ to Operand[]\n"
    "    endof\n"
    "\n"
    "  endcase\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* handler for ZK_STARTMARKER ...                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchOP_StartMarker \\\\handler\n"
    "\n"
    "  //\\\"Operand:- ZK_STARTMARKER\\\" .verbose\n"
    "\n"
    "  0 locals| iPhrases |\n"
    "\n"
    "  <tableNm> op__table if\n"
    "    table[].tablePtn@ to tablePtn[]\n"
    "    Pipein[].pipeOut\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // generate the plan for the fetch\n"
    "  generatePlan\n"
    "\n"
    "  //planner[].showPaths\n"
    "\n"
    "  // assert we have a plan\n"
    "  planner[].isNull not assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch request                                      (on node where spawned) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetchOP_req \\\\operator\n"
    "\n"
    "  LogReqEntry SEED_REQ\n"
    "  <tableNm> <predicate> \\\"PARAMETERS %v %v\\\" str.format .\n"
    "\n"
    "  op__topology\n"
    "\n"
    "  find: fetchOP_CancelMarker ZK_CANCELMARKER op[].handler!\n"
    "  find: fetchOP_CrwBuffer    ZK_CRWBUFFER    op[].handler!\n"
    "  find: fetchOP_PulseMarker  ZK_PULSEMARKER  op[].handler!\n"
    "  find: fetchOP_StartMarker  ZK_STARTMARKER  op[].handler!\n"
    "\n"
    "  op__loop\n"
    "\n"
    "  LogReqExit\n"
    "  job::deleteThis\n"
    "  DONE_REQ_OP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: fetchOP :: fetchOP <tableNm> <predicate> ;\n"
    "\n"
    ": fetchOP opInfo tagCopy: localOp_tags\n"
    "  tags{ <jobDesc> = \\\"--description of operator--\\\" }\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_fetch.sen"_Stz
  ;

