    ": munge_WriteSenConstant ( pCppFile pSenFile -- )\n"
    "\n"
    "  params| pSenFile pCppFile |\n"
    "\n"
    "  \\\"  \\\\\\\" CONSTANT \\\" pCppFile file.write\n"
    "  pSenFile file.path@ pCppFile file.write\n"
    "  \\\"\\\\\\\"_Stz\\\\n\\\" pCppFile file.write\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put a ; terminator for statement into c++ file                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_WriteCppTerm ( pCppFile pSenFile -- )\n"
    "\n"
    "  params| pSenFile pCppFile |\n"
    "\n"
    "  \\\"  ;\\\\n\\\" pCppFile file.write\n"
    "\n"
    "  \\\"\\\\n\\\" pCppFile file.write\n"
    "\n"
    "  \\\"  vCompileMungedColon(sFileContents);\\\\n\\\" pCppFile file.write\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write the .cpp footer portion of the file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_WriteCppFooter ( pCppFile -- )\n"
    "\n"
    "  params| pCppFile |\n"
    "\n"
    "  \\\"}\\\\n\\\" pCppFile file.write\n"
    "  \\\"\\\\n\\\" pCppFile file.write\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  pCppFile file.write\n"
    "  \\\"\\\\n\\\" pCppFile file.write\n"
    "\n"
    "  \\\"/* end                                                                        */\\\"\n"
    "  pCppFile file.write\n"
    "  \\\"\\\\n\\\" pCppFile file.write\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  pCppFile file.write\n"
    "  \\\"\\\\n\\\" pCppFile file.write\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* produce a c++ statement for the sen file                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProduceCppStatement ( pCppFile pSenFile -- )\n"
    "\n"
    "  params| pSenFile pCppFile |\n"
    "\n"
    "  pCppFile pSenFile munge_WriteCppVariable\n"
    "\n"
    "  pCppFile pSenFile munge_WriteSenText\n"
    "\n"
    "  pCppFile pSenFile munge_WriteSenConstant\n"
    "\n"
    "  pCppFile pSenFile munge_WriteCppTerm\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge one .sen file                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProcessSenFile ( pCppFile sSenFileNm -- )\n"
    "\n"
    "  params| sSenFileNm pCppFile |\n"
    "\n"
    "  file::new locals| pSenFile |\n"
    "\n"
    "  sSenFileNm OPEN_READ pSenFile file.open assert\n"
    "\n"
    "  pCppFile pSenFile munge_ProduceCppStatement\n"
    "\n"
    "  // close and delete the file accessor\n"
    "  pSenFile file.close\n"
    "  pSenFile file.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files in the sen dir                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge_ProcessDir ( pCppFile pSenDir -- )\n"
    "\n"
    "  params| pSenDir pCppFile |\n"
    "\n"
    "  // read thru directory\n"
    "  begin pSenDir dir.read while\n"
    "\n"
    "    // ignore entries which aren't regular files\n"
    "    pSenDir dir.entryType DE_REG == not continue\n"
    "\n"
    "    // ignore entries which aren't .sen files\n"
    "    4 pSenDir dir.entryName str.right \\\".sen\\\" str.equal not continue\n"
    "    pSenDir dir.entryName .\n"
    "\n"
    "    // convert to C++\n"
    "    pCppFile pSenDir dir.entryName munge_ProcessSenFile\n"
    "\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge prompt\n"
    "\n"
    "  \\\"munging\\\" .\n"
    "\n"
    "  // create a directory accessor\n"
    "  file::new dir::new \\\"\\\" locals| origDir pSenDir pCppFile |\n"
    "\n"
    "  // save original dir and change to ../Sen\n"
    "  dir::getCurrent to OrigDir\n"
    "\n"
    "  \\\"../Sen\\\" dir::changeCurrent\n"
    "  dir::getCurrent \\\"Current working directory now: %v\\\" str.format .\n"
    "\n"
    "  // open sen directory\n"
    "  \\\".\\\" pSenDir dir.open assert\n"
    "\n"
    "  // open cpp file\n"
    "  \\\"../Munge/Task_AddMunged.cpp\\\" OPEN_WRITE pCppFile file.open assert\n"
    "\n"
    "  pCppFile munge_WriteCppHeader\n"
    "\n"
    "  // munge the command dir\n"
    "  pCppFile pSenDir munge_ProcessDir\n"
    "\n"
    "  pCppFile munge_WriteCppFooter\n"
    "\n"
    "  // close and delete file accessor\n"
    "  pCppFile file.close\n"
    "  pCppFile file.delete\n"
    "\n"
    "  // close and delete directory accessor\n"
    "  pSenDir dir.close\n"
    "  pSenDir dir.delete\n"
    "\n"
    "  // change back to original dir\n"
    "  origDir dir::changeCurrent\n"
    "  dir::getCurrent \\\"Current working directory now: %v\\\" str.format .\n"
    "\n"
    "  \\\"munged\\\" .\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT se_munge.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_LoadTable.sen

  sFileContents =
    "\""
    "\\\"munged job_LoadTable.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_LoadTable.sen -- Job Load Table                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_LoadTable.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on participating node                           //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* read chunks from input, and write each record behind                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LoadTable_process ( pJob_LoadTable -- )\n"
    "\n"
    "  params| pJob_LoadTable |\n"
    "\n"
    "  pJob_LoadTable job_loadTable.begin not if exit then\n"
    "\n"
    "  begin pJob_LoadTable job_loadTable.chunk while repeat\n"
    "\n"
    "  pJob_LoadTable job_loadTable.end\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* spawn sub-loaders                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LoadTable_spawnSubs ( pJob_LoadTable -- )\n"
    "\n"
    "  params| pJob_LoadTable |\n"
    "\n"
    "  task[] task.grabLock\n"
    "\n"
    "  grid::slots task[] task.acks!\n"
    "\n"
    "  args.subLoaders 0\n"
    "  do\n"
    "    pJob_LoadTable job_subLoader::spawn\n"
    "  loop\n"
    "\n"
    "  task::wait\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute load table on this participant node (same as originator)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LoadTable_executeLoad ( pJob_LoadTable --  )\n"
    "\n"
    "  params| pJob_LoadTable |\n"
    "\n"
    "  0 locals| sTableNm  |\n"
    "  0 locals| pTable    |\n"
    "\n"
    "  //\\\"LoadTable_executeLoad: Executing loader on this node\\\" .\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // initialise\n"
    "\n"
    "  // set table dictionary\n"
    "  <tableNm> to sTableNm\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "  // get table\n"
    "  sTableNm find execute to pTable\n"
    "  pTable pJob_LoadTable Job_LoadTable.table!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // chunk the file being loaded\n"
    "\n"
    "  pJob_LoadTable LoadTable_process\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // spawn and wait for sub-loaders\n"
    "\n"
    "  pJob_LoadTable LoadTable_spawnSubs\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* this table load job waits for an ack only                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LoadTable_waitOnly ( pJob_LoadTable --  )\n"
    "\n"
    "  task[] task.grabLock\n"
    "  grid::slots task[] task.acks!\n"
    "  task::wait\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* Job_LoadTable request (on originating node)                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LoadTable_req (  -- <R> )\n"
    "\n"
    "  LogEntry SEED_REQ\n"
    "\n"
    "  job[] locals| pJob_LoadTable |\n"
    "\n"
    "  // add job to originator list and distribute\n"
    "  pJob_LoadTable job.distribute\n"
    "\n"
    "  LogExit DONE_REQ\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* execute Job_LoadTable job (on each participating node)                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable_exe ( -- )\n"
    "\n"
    "  LogEntry SEED_EXE\n"
    "\n"
    "  job[] locals| pJob_LoadTable |\n"
    "\n"
    "  0 locals| iOriginNode |\n"
    "\n"
    "  pJob_LoadTable job.id@ job::originator@ to iOriginNode\n"
    "\n"
    "  iOriginNode node::isOrigin if\n"
    "    pJob_LoadTable LoadTable_executeLoad\n"
    "  else\n"
    "    LoadTable_waitOnly\n"
    "  then\n"
    "\n"
    "  pJob_LoadTable job::participantExecuted\n"
    "\n"
    "  LogExit DONE_EXE\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check resources (on participating nodes)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable.checkResources ( pJob_LoadTable -- )\n"
    "\n"
    "  LogEntry Check_Resources\n"
    "\n"
    "  params| pJob_LoadTable  |\n"
    "\n"
    "  0 locals| pFile |\n"
    "  0 locals| iOriginNode |\n"
    "\n"
    "  //pJob_LoadTable job.objectName@ locals| sTableNm |\n"
    "  <tableNm> locals| sTableNm |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check for sufficient memory\n"
    "\n"
    "  node::checkEnoughBuffers not if pJob_LoadTable ERROR_JOB !!logError exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if file exists (SHOULDN\\\"T THIS BE ONLY ON ORIGINATING NODE?)\n"
    "\n"
    "  pJob_LoadTable job.id@ job::originator@ to iOriginNode\n"
    "\n"
    "  iOriginNode node::isOrigin if\n"
    "\n"
    "    file::new to pFile\n"
    "\n"
    "    pJob_LoadTable job_LoadTable.filePath@ OPEN_READ pFile file.open\n"
    "    not if\n"
    "       pFile file.delete assert::stack_0 EC_INVALID_FILE pJob_LoadTable ERROR_JOB !!logError exit\n"
    "    then\n"
    "\n"
    "    pFile file.close pFile file.delete assert::stack_0\n"
    "\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // grab a ddl lock\n"
    "\n"
    "  DdlLock[].grabRead\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm folder[].checkIsTablesFolder not if pJob_LoadTable ERROR_JOB !!logError exit then\n"
    "  //sTableNm \\\"In table folder: %v\\\" .printf\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  //path[].dump\n"
    "\n"
    "  // check it is a table\n"
    "  sTableNm name::checkIsTable not if path[].discardTableFolder pJob_LoadTable ERROR_JOB !!logError exit then\n"
    "\n"
    "  // pop table dictionary\n"
    "  path[].discardTableFolder\n"
    "  //path[].dump\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if we have enough buffers\n"
    "\n"
    "  node::testEnoughBuffers not if pJob_LoadTable ERROR_JOB !!logError exit then\n"
    "\n"
    "  LogExit Resources_Checked\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* release resources (on participating nodes)                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable.releaseResources ( pJob_LoadTable -- )\n"
    "\n"
    "  LogEntry Release_Resources\n"
    "\n"
    "  params| pJob_LoadTable  |\n"
    "\n"
    "  LogExit Resources_Released\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin job (on participating nodes)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable_beg ( -- )\n"
    "\n"
    "  LogEntry SEED_BEG\n"
    "\n"
    "  job[] locals| pJob_LoadTable |\n"
    "\n"
    "  pJob_LoadTable job.becomeParticipant\n"
    "\n"
    "  pJob_LoadTable loadTable.checkResources\n"
    "\n"
    "  job::participantBegun\n"
    "\n"
    "  LogExit DONE_BEG\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end job (on participating nodes)                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable_end ( -- )\n"
    "\n"
    "  LogEntry SEED_END\n"
    "\n"
    "  job[] locals| pJob_LoadTable |\n"
    "\n"
    "  pJob_loadTable loadTable.releaseResources\n"
    "\n"
    "  job::participantEnded\n"
    "\n"
    "  LogExit DONE_END\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* cancel job (on participating nodes)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadTable_can ( -- )\n"
    "\n"
    "  LogEntry SEED_CAN\n"
    "\n"
    "  job[] locals| pJob_LoadTable |\n"
    "\n"
    "  pJob_LoadTable loadTable.releaseResources\n"
    "\n"
    "  job::participantCancelled\n"
    "\n"
    "  LogExit DONE_CAN\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_LoadTable.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
