  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of OP_changeFolder.sen

  sFileContents =
    "\""
    "\\\"munged OP_changeFolder.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_changeFolder.sen -- Operator change flolder                             */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_changeFolder.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cf_action\n"
    "\n"
    "  0 0 locals| pCurrentFolder sFolderNm |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // get the folderNm from the the tag\n"
    "  <folderNm> to sFolderNm\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"..\\\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \\\"..\\\" str.equal if\n"
    "    folder[] dic.name@ \\\"tenants\\\" str.equal not if path[].discardFolder then\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"~\\\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \\\"~\\\" str.equal if\n"
    "    begin folder[] dic.name@ \\\"tenants\\\" str.equal not while path[].discardFolder repeat\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default catalogs\n"
    "  sFolderNm \\\"~catalogs\\\" str.equal if\n"
    "    setCatalogs\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default schemas\n"
    "  sFolderNm \\\"~schemas\\\" str.equal if\n"
    "    setSchemas\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // set default tables\n"
    "  sFolderNm \\\"~tables\\\" str.equal if\n"
    "    setTables\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // test for a \\\"tenants\\\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \\\"tenants\\\" str.equal if\n"
    "    path[].discardFolderAll\n"
    "    attachmap::tenants@ execute path[].pushFolder\n"
    "    setPath\n"
    "    true\n"
    "    exit                                                         // *EARLY EXIT*\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // otherwise we expect a name of a sub-folder to which we push path to\n"
    "  //  push sub-folder\n"
    "\n"
    "  sFolderNm folder[].findSymbol to pCurrentFolder\n"
    "\n"
    "  pCurrentFolder word.isFolder not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  pCurrentFolder execute path[].pushFolder\n"
    "  setPath\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: cf :: cf <folderNm> ;\n"
    "\n"
    ": cf opInfo tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <jobDesc>     = \\\"--description of operator--\\\"\n"
    "    <localLiteOp> = true\n"
    "    <params>      = 1\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_changeFolder.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


