  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of op__compiler.sen

  sFileContents =
    "\""
    "\\\"munged op__compiler.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* op__compiler.sen -- operator compiler words                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" op__compiler.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": opSyntax:\n"
    "\n"
    "  // create a word using next token from input source as the word name\n"
    "\n"
    "  input::next locals| sOpNm |\n"
    "\n"
    "  sOpNm series-name \\\"_syntax\\\" str.cat :create\n"
    "\n"
    "  // set the word category to be jobSyntax\n"
    "  //[ compiler::current@ , ] compiler::current@ word.category!\n"
    "  find: jobSyntax: compiler::current@ word.category!\n"
    "\n"
    "  // attach an ename set to the word being created\n"
    "  tagSet::new locals| pTagSet |\n"
    "\n"
    "  pTagSet compiler::current@ word.TagSet!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"__name__\\\" sOpNm\n"
    "    pTagSet tagSet.appendStr\n"
    "\n"
    "  // skip the :: token from input source\n"
    "  input::next discard\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"__job__\\\" \\\"CN_JOB_UNIVERSAL\\\"\n"
    "  pTagSet tagSet.appendStr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // parse each input token till ';', build ename set representing the syntax\n"
    "  begin\n"
    "    input::next\n"
    "    dup \\\";\\\" str.equal not\n"
    "    while\n"
    "\n"
    "      dup str.isMetaToken if\n"
    "        // dup \\\"%v is a meta token\\\" .printf\n"
    "        // add (\\\"*\\\",meta,TN_STRING) in ename set\n"
    "        \\\"__meta__\\\" swap pTagSet tagSet.appendStr\n"
    "\n"
    "      else dup str.isJsonToken if\n"
    "        // dup \\\"%v is a json token\\\" .printf\n"
    "        // add (\\\"*\\\",json,TN_STRING) in ename set\n"
    "        \\\"__json__\\\" swap pTagSet tagSet.appendStr\n"
    "\n"
    "      else dup \\\"__etc__\\\" str.equal if\n"
    "        \\\"__etc__\\\"  swap pTagSet tagSet.appendStr\n"
    "\n"
    "      else\n"
    "        // dup \\\"%v is a normal token\\\" .printf\n"
    "        // add (word,\\\"\\\",TN_STRING) in ename set\n"
    "        dup pTagSet tagSet.appendStr\n"
    "\n"
    "      then then then\n"
    "  repeat\n"
    "\n"
    "  // discard the \\\";\\\" from dstack\n"
    "  discard\n"
    "\n"
    "  // pTagSet tagSet.asStr .\n"
    "\n"
    "  does>\n"
    "    // ..to be written\n"
    "    discard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* promote current word to be an _opInfo word                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": opInfo immediate\n"
    "\n"
    "  compiler::current@ locals| pWord |\n"
    "\n"
    "  // set the name of the word to be _info\n"
    "  pWord word.name@\n"
    "    \\\"_info\\\" str.cat\n"
    "    pWord word.name!\n"
    "\n"
    "  // set the word category to be opInfo\n"
    "  find: opInfo pWord word.category!\n"
    "\n"
    "  // attach an ename set to the word being created\n"
    "  tagSet::new locals| pWordTagSet |\n"
    "  pWordTagSet pWord word.TagSet!\n"
    "\n"
    "  // add <jobNm> tag\n"
    "  \\\"<jobNm>\\\" pWord word.name_trunc pWordTagSet tagSet.insertStr\n"
    "\n"
    "  pWord encode::call\n"
    "    POSTPONE word.tagSet@\n"
    "\n"
    "  //does>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* complete the info for all ops                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::ops\n"
    "\n"
    "  find: opInfo locals| pOpInfo |\n"
    "\n"
    "  // iterate thru all pOpInfo words\n"
    "\n"
    "  dic::root dic.lastWord dup\n"
    "  iterate                                // iterate word cursor\n"
    "\n"
    "    object@ word.category@ pOpInfo eql if\n"
    "      // object@ word.dump\n"
    "      // object@ word.tagSet@ tagSet.asStr .\n"
    "\n"
    "      object@ word.name@ \\\"Filling out: %v\\\" .printf\n"
    "      \n"
    "      object@ fillOut::tagSet_ofInfoWord  // fill out the tag set of the op\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!            // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": wordCats prompt\n"
    "\n"
    "  0 0 locals| pWord pCatg |\n"
    "\n"
    "  dic::root dic.lastWord dup\n"
    "  iterate                                 // iterate word cursor\n"
    "\n"
    "    object@ to pWord\n"
    "\n"
    "    pWord word.show\n"
    "\n"
    "    object@ word.prev object!             // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT op__compiler.sen"_Stz
  ;

