  // munge of OP_listFolders.sen

  sFileContents =
    "\""
    "\\\"munged OP_listFolders.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* OP_listFolders.sen -- Operator list folder                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" OP_listFolders.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* action                                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf_action\n"
    "\n"
    "  // find the __ table\n"
    "  <streamDef> op__tableDef_streamSet assert\n"
    "\n"
    "  // create a new streamDef\n"
    "  streamSetTable[] streamDef[].new\n"
    "\n"
    "  // pipeout the streamDef\n"
    "  streamDef[].pipeout\n"
    "\n"
    "  // create a streamSet operand\n"
    "  streamSetTable[] streamSet[].new\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // insert a row in the infoSet for each word\n"
    "\n"
    "  folder[] dic.lastWord dup\n"
    "  iterate                          // setup iteration of words\n"
    "\n"
    "    object@ word.isTable if\n"
    "    \\\"table\\\"\n"
    "    then\n"
    "\n"
    "    object@ word.isIndex if\n"
    "    \\\"index\\\"\n"
    "    then\n"
    "\n"
    "    object@ isFolder if\n"
    "      object@ execute dic.kind@ word.name@\n"
    "    then\n"
    "\n"
    "    object@ word.name@\n"
    "    streamSetTable[] StreamSet[].addListFolder not if\n"
    "      StreamSet[].pipeout\n"
    "      streamSetTable[] streamSet[].new\n"
    "      object@ word.name@\n"
    "      streamSetTable[] StreamSet[].addListFolder assert\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!      // step backwards thru words\n"
    "  next\n"
    "\n"
    "  // pipeout the infoset\n"
    "  StreamSet[].pipeout\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "opSyntax: lf :: lf ;\n"
    "\n"
    ": lf opInfo tagCopy: localLiteOp_tags\n"
    "  tags{\n"
    "    <jobDesc>     = \\\"--description of operator--\\\"\n"
    "    <localLiteOp> = true\n"
    "    <streamDef>   = __listFolder\n"
    "    <params>      = 0\n"
    "  }\n"
    " ;\n"
    "    \n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT OP_listFolders.sen"_Stz
  ;

