  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_WriteBuffer.sen

  sFileContents =
    "\""
    "\\\"munged job_WriteBuffer.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_WriteBuffer.sen -- Write Buffer Job                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_WriteBuffer.sen\\\" .verbose\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                               on kid node                                  //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* load buffer into table                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": WriteBuffer.insert ( pJob_WriteBuffer -- )\n"
    "\n"
    "  params| pJob_WriteBuffer |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  0 locals| pJob_InsertTable  |\n"
    "\n"
    "  0 locals| sTableNm    |\n"
    "  0 locals| i_Partition |\n"
    "  0 locals| bAllLoaded  |\n"
    "  0 locals| pJob_Parent |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //\\\"WriteBuffer.insert :\\\" .verbose\n"
    "  //pJob_WriteBuffer job.show\n"
    "\n"
    "  // get table name\n"
    "  //pJob_WriteBuffer job.objectName@ to sTableNm\n"
    "  <tableNm> to sTableNm\n"
    "\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "  // use table name find and set target table\n"
    "  sTableNm find execute locals| pTable |\n"
    "\n"
    "  // set the table in the writeBuffer and its rowBuffer\n"
    "// ALKA: should these be two steps ?\n"
    "  pTable pJob_WriteBuffer Job_WriteBuffer.Table!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get the parent job (participant node)\n"
    "  // parent job can be EndInsert of LoadTable\n"
    "  pJob_WriteBuffer Job_WriteBuffer.parentJobId@ locals| iParentJobId |\n"
    "\n"
    "  // we wait till the parent job can be found in the participant job skip list\n"
    "  // there is a possiblity that the buffer arrives on a node before the parent job\n"
    "  pJob_WriteBuffer Job_WriteBuffer.isLoading if\n"
    "    pJob_WriteBuffer iParentJobId job::waitParticipant to pJob_Parent\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // grab write lock on table partition\n"
    "  pJob_WriteBuffer Job_WriteBuffer.partition@ to i_Partition\n"
    "  i_Partition pTable tablePtnGrabWrite\n"
    "\n"
    "  // now insert the buffer of rows\n"
    "  pJob_WriteBuffer Job_WriteBuffer.insertRows to bAllLoaded\n"
    "\n"
    "  // drop write lock on table partition\n"
    "  i_Partition pTable tablePtnDropWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // ack the load table task if all buffers have been loaded\n"
    "  bAllLoaded if\n"
    "\n"
    "    // we wait till the parent job can be found in the participant job skip list\n"
    "    // there is a possiblity that the buffer arrives on a node before the parent job\n"
    "    pJob_WriteBuffer Job_WriteBuffer.isInserting if\n"
    "      pJob_WriteBuffer iParentJobId job::waitParticipant to pJob_Parent\n"
    "    then\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // first check if the job is executing SS_SEED_EXE\n"
    "    // then get the task that is executing it\n"
    "    begin\n"
    "      pJob_Parent job.IsExecuting\n"
    "    not while\n"
    "      1 thread::sleepMsec\n"
    "    repeat\n"
    "\n"
    "    pJob_Parent job.task@ locals| pTask_Parent |\n"
    "\n"
    "    // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "    // wait for acks to be set in the endInsert task\n"
    "    begin\n"
    "       pTask_Parent task.IsAckSet\n"
    "    not while\n"
    "       1 thread::sleepMsec\n"
    "    repeat\n"
    "\n"
    "    //\\\"WriteBuffer.insert acking parentJob(endInsert/loadTable):\\\" .verbose\n"
    "    pTask_Parent task.grabLock\n"
    "    pTask_Parent task.dropLock\n"
    "    pTask_Parent task.ack\n"
    "\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* seed on kid node                                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": writeBuffer_kid ( -- )\n"
    "\n"
    "  LogEntry SEED_RUN\n"
    "\n"
    "  job[] locals| pJob_WriteBuffer |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check there is enough buffers and load\n"
    "\n"
    "  // node::checkEnoughBuffers if\n"
    "  pJob_WriteBuffer writeBuffer.insert\n"
    "  //then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  LogExit\n"
    "  job::deleteThis\n"
    "\n"
    "  DONE_KID\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "//                            on loading node                                 //\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forward this load buffer job to kid node                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": WriteBuffer.forward ( pJob_WriteBuffer -- )\n"
    "\n"
    "  params| pJob_WriteBuffer |\n"
    "\n"
    "  // which partition are we forwarding to?\n"
    "  pJob_WriteBuffer Job_WriteBuffer.partition@ locals| i_Partition |\n"
    "\n"
    "  // convert i_Partition to i_ForwardNode\n"
    "  i_Partition grid::toNode locals| i_ForwardNode |\n"
    "\n"
    "  //i_Partition i_ForwardNode \\\"WriteBuffer.forward : Node %v Partition %v\\\" .printf\n"
    "\n"
    "  // send this job to the forward node\n"
    "  //i_ForwardNode pJob_WriteBuffer job.forward\n"
    "\n"
    "  i_ForwardNode grid::thisNode@ == if\n"
    "    //\\\"not forwarding\\\" .\n"
    "    // on same node, just spawn/reseed job on same node\n"
    "    pJob_WriteBuffer JM_SEED_RCV job.reseed\n"
    "    false\n"
    "  else\n"
    "    // send this job to the forward node\n"
    "    //\\\"forwarding\\\" .\n"
    "    i_ForwardNode pJob_WriteBuffer job.forward\n"
    "    true\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* seed on inserting node                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": writeBuffer_run (  -- )\n"
    "\n"
    "  LogEntry SEED_RUN\n"
    "\n"
    "  job[] locals| pJob_WriteBuffer  |\n"
    "\n"
    "  //\\\"pJob_WriteBuffer :\\\" .verbose\n"
    "\n"
    "  // simply forward this job to kid node\n"
    "  pJob_WriteBuffer writeBuffer.forward\n"
    "\n"
    "  true == if\n"
    "    job::deleteThis\n"
    "  else\n"
    "    // nullptr task[] task.job!\n"
    "  then\n"
    "\n"
    "  DONE_RUN\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_WriteBuffer.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


