  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of se_prompt.sen

  sFileContents =
    "\""
    "\\\"munged se_prompt.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_prompt.sen -- prompt related words                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" se_prompt.sen\\\" .verbose\n"
    "\n"
    ": article_dump prompt article::dump ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Task_Interpret_line\n"
    "  \n"
    "  // -- -- -- -- -- -- --\n"
    "  // get next input token\n"
    "  input::read\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // test for end of input?\n"
    "  input::kind@ TN_NULL == if\n"
    "    //\\\"!!NONE!!\\\" .put\n"
    "    true exit_rt\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // is token an integer?\n"
    "  input::kind@ TN_INTEGER == if\n"
    "\n"
    "    input::token >int        // convert str to int, leave on stack\n"
    "\n"
    "    compiler::isPostponing if\n"
    "      \\\"SHOULD NOT BE POSTPONING AN INT\\\" .put\n"
    "      process::quit\n"
    "      reenter\n"
    "    then\n"
    "\n"
    "    compiler::isCompiling if\n"
    "      encode::push           // compile encodes push intval\n"
    "      reenter\n"
    "    then\n"
    "\n"
    "    reenter                  // interpret leaves int on stack\n"
    "\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // is token a string?\n"
    "  input::kind@ TN_STRING == if\n"
    "\n"
    "    input::token             // put str on stack\n"
    "\n"
    "    compiler::isPostponing if\n"
    "      \\\"SHOULD NOT BE POSTPONING A STR\\\" .put\n"
    "      process::quit\n"
    "      reenter\n"
    "    then\n"
    "\n"
    "    compiler::isCompiling if\n"
    "      encode::push           // compile encodes push stzVal\n"
    "      reenter\n"
    "    then\n"
    "\n"
    "    reenter                  // interpret leaves str on stack\n"
    "\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // token should be a name\n"
    "  input::kind@ TN_NAME != if\n"
    "    \\\"strange token\\\" .put input::kind@ .put\n"
    "    reenter\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // test for bye\n"
    "  input::token \\\"bye\\\" str.equal if\n"
    "    false exit_rt\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // is token a known word?\n"
    "  input::token word::find\n"
    "  dup not if\n"
    "    discard                     // token is an unknown word\n"
    "    input::unknown\n"
    "    reenter\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // pWord now on d-stack\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // is an immediate word?\n"
    "  dup word.isImmediate if\n"
    "   execute                   // execute the immediate word\n"
    "   reenter\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // postponing mode?\n"
    "  compiler::isPostponing if\n"
    "    \\\"POSTPONING\\\" .put\n"
    "    encode::push\n"
    "    \\\"encode::call\\\" word::find encode::call\n"
    "    reenter\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // compiling mode?\n"
    "  compiler::isCompiling if\n"
    "    encode::call                 // encode::call encodes call to word\n"
    "    reenter\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- --\n"
    "  // we are interpreting\n"
    "  execute                    // execute word\n"
    "\n"
    "  reenter                    // loop over\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": Task_Interpreter\n"
    "  \n"
    "  //debug::breakpoint\n"
    "\n"
    "  input::push\n"
    "  input::stdin\n"
    "  input::useBegin\n"
    "\n"
    "  begin\n"
    "    \\\"SE Task> \\\" .put\n"
    "\n"
    "  Task_Interpret_line while repeat\n"
    "\n"
    "  //debug::breakpoint\n"
    "\n"
    "  input::useEnd\n"
    "  input::pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dbg>\n"
    "\n"
    "  \\\"path::\\\" .put .\\\\n\n"
    "\n"
    "  \\\"symbols\\\" find execute\n"
    "\n"
    "  stk\n"
    "  rstk\n"
    "\n"
    "  input::push\n"
    "  input::stdin\n"
    "  input::useBegin\n"
    "\n"
    "  begin\n"
    "    \\\"dbg> \\\" .put\n"
    "\n"
    "  Task_Interpret_line while repeat\n"
    "\n"
    "  //debug::breakpoint\n"
    "\n"
    "  input::useEnd\n"
    "  input::pop\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT se_prompt.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


