  // munge of op__common.sen

  sFileContents =
    "\""
    "\\\"munged op__common.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* op__common.sen -- operator common words                                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" op__common.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm> of tabledef                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__file ( fileNm mode -- )\n"
    "\n"
    "  params| mode sFileNm |\n"
    "\n"
    "  // open the file for reading\n"
    "  file::new to File0[]\n"
    "  sfileNm mode File0[].get file.open\n"
    "  if\n"
    "    true\n"
    "  else\n"
    "    File0[].get file.delete assert::stack_0 nullptr File0[].set EC_INVALID_FILE\n"
    "    op.pipelineJob@ ERROR_JOB !!logError\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "  then\n"
    "  ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm> of tabledef                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__tableDef_infoSet ( tableNm -- )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // save current path\n"
    "  path[].save\n"
    "\n"
    "  // move to default tables folder\n"
    "  \\\"/tenants/boray/catalogs/rapidsse/schemas/public/tables\\\"\n"
    "  str.toStrVec path[].set\n"
    "\n"
    "  // table\n"
    "  sTableNm name::checkIsValidTable assert\n"
    "\n"
    "  // move to table folder and find the table\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  sTableNm find execute to infoSetTable[]\n"
    "\n"
    "  // cross-check\n"
    "  infoSetTable[] assert\n"
    "\n"
    "  path[].discardTableFolder\n"
    "\n"
    "  // restore path\n"
    "  path[].restore\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm> of tabledef                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__tableDef_streamSet ( tableNm -- )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // save current path\n"
    "  path[].save\n"
    "\n"
    "  // move to default tables folder\n"
    "  \\\"/tenants/boray/catalogs/rapidsse/schemas/public/tables\\\"\n"
    "  str.toStrVec path[].set\n"
    "\n"
    "  // table\n"
    "  sTableNm name::checkIsValidTable assert\n"
    "\n"
    "  // move to table folder and find the table\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  sTableNm find execute to streamSetTable[]\n"
    "\n"
    "  // cross-check\n"
    "  streamSetTable[] assert\n"
    "\n"
    "  path[].discardTableFolder\n"
    "\n"
    "  // restore path\n"
    "  path[].restore\n"
    "\n"
    "  true\n"
    "  ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm>                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__table ( tableNm -- )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  folder[].checkInTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // table\n"
    "  sTableNm name::checkIsValidTable not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // move to table folder and find the table\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  sTableNm find execute to table[]\n"
    "  path[].discardTableFolder\n"
    "\n"
    "  // cross-check\n"
    "  table[] assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <indexNm>                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__index ( tableNmm indexNm )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  folder[].checkInTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // move to table folder\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // move to indexes folder\n"
    "  path[].pushIndexesFolder assert\n"
    "\n"
    "  sIndexNm name::checkIsIndex not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    path[].discardTableFolder\n"
    "    path[].discardIndexesFolder\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  sIndexNm find execute to index[]\n"
    "\n"
    "  // cross-check\n"
    "  index[] assert\n"
    "\n"
    "  path[].discardTableFolder\n"
    "  path[].discardIndexesFolder\n"
    "\n"
    "  //pathStr .\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* verify and set folder to <tableNm>, then to <indexNm>                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__table_index ( tableNm indexNm )\n"
    "\n"
    "  params| sIndexNm sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  folder[].checkInTables not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // table\n"
    "  sTableNm name::checkIsValidTable not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    false\n"
    "  exit\n"
    "  then\n"
    "\n"
    "  // move to table folder and find the table\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  sTableNm find execute to table[]\n"
    "\n"
    "  // cross-check\n"
    "  table[] assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // move to indexes folder\n"
    "  path[].pushIndexesFolder assert\n"
    "\n"
    "  sIndexNm name::checkIsIndex not if\n"
    "    op.pipelineJob@ ERROR_JOB\n"
    "    Pipein[].delete\n"
    "    Operand[].newErrorMarker\n"
    "    Operand[].pipeout\n"
    "    path[].discardTableFolder\n"
    "    path[].discardIndexesFolder\n"
    "    false\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  sIndexNm find execute to index[]\n"
    "\n"
    "  // cross-check\n"
    "  index[] assert\n"
    "\n"
    "  path[].discardTableFolder\n"
    "  path[].discardIndexesFolder\n"
    "\n"
    "  //pathStr .\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set operator topology, next stage and op                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__topology\n"
    "\n"
    "  op[].init\n"
    "\n"
    "  // set topolgy in the op\n"
    "  <topology> op.topology!\n"
    "\n"
    "  // set nextStage in op\n"
    "  <nextStage> op.nextStage!\n"
    "\n"
    "  // set nextOp in op\n"
    "  <nextOp> op.nextOp!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* default operator loop                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": op__loop\n"
    "\n"
    "  begin\n"
    "\n"
    "    Operand[].isNull if\n"
    "\n"
    "      // bide till next operand is available\n"
    "      Pipein[].bide\n"
    "\n"
    "      // pop next operand from queue into Pipein[]\n"
    "      Pipein[].next\n"
    "\n"
    "      // execute the operator's handler for the operand\n"
    "      Pipein[].kind op[].handler@ execute\n"
    "\n"
    "    else\n"
    "\n"
    "      // get the Out-of_Order Operand\n"
    "      OperandOoO[].next if\n"
    "\n"
    "        OperandOoO[] to Pipein[]\n"
    "        nullptr to OperandOoO[]\n"
    "\n"
    "        // execute the operator's handler for the Out-of_Order operand\n"
    "        Pipein[].kind op[].handler@ execute\n"
    "\n"
    "        // assert Operand is null\n"
    "        Operand[].isNull assert\n"
    "\n"
    "      else\n"
    "\n"
    "        // execure operand handler\n"
    "        Operand[].kind op[].handler@ execute\n"
    "\n"
    "      then\n"
    "\n"
    "    then\n"
    "\n"
    "  while assert::stack_0 repeat\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerNew\n"
    "\n"
    "  timer::new    to timer[]\n"
    "  aggTimer::new to aggTimer[]\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerBegin\n"
    "\n"
    "  timer[] timer.start\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BM_TimerUpdate\n"
    "\n"
    "  timer[] timer.update\n"
    "\n"
    "  timer[] timer.ticks aggTimer[] aggTimer.add\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT op__common.sen"_Stz
  ;

