  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of db_table.sen

  sFileContents =
    "\""
    "\\\"munged db_table.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* db_table.sen -- table related words                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" db_table.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the table category                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": \\\\table \\\\\\\\category ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if word is a table                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.isTable\n"
    "\n"
    "  word.category@ find: \\\\table eql\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the table folder and push it onto task dictionary                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].pushTableFolder ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  find execute path[].pushFolder\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the table folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": path[].discardTableFolder\n"
    "\n"
    "  path[].discardFolder\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if current folder is ../tables                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].isTables ( -- t|f )\n"
    "\n"
    "  folder[] dic.name@ \\\"tables\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check current folder is ../tables                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].checkInTables ( -- t|f )\n"
    "\n"
    "  folder[].isTables if true exit then\n"
    "\n"
    "  EC_NOT_IN_TABLES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check there is a table folder                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": folder[].checkIsTablesFolder  ( \\\"<tableName>\\\" -- )\n"
    "\n"
    "  folder[].findSymbol not if EC_NO_SUCH_TABLE false exit then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if column is a valid column of the table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::checkIsColumn ( \\\"<columnNm>\\\" \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  params| sTableNm sColumnNm |\n"
    "  0 locals| pTable |\n"
    "\n"
    "  sTableNm find execute to pTable\n"
    "  sColumnNm pTable table.isColumn if true exit then\n"
    "\n"
    "  EC_INVALID_COLUMN false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check given name is a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::checkIsTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  find ( \\\"<tableNm>\\\" ^w:table )\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "  not ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    discard ( \\\"<tableNm>\\\" )\n"
    "    discard ( )\n"
    "    EC_NO_SUCH_TABLE false ( errorCode false )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<tableNm>\\\" ^w:table ^w:table )\n"
    "\n"
    "  word.category@ ( \\\"<tableNm>\\\" ^w:table ^word )\n"
    "  find: \\\\table ( \\\"<tableNm>\\\" ^w:table ^word ^word )\n"
    "  eql ( \\\"<tableNm>\\\" ^w:table bool )\n"
    "  if\n"
    "    discard ( \\\"<tableNm>\\\" )\n"
    "    true ( \\\"<tableNm>\\\" true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  discard ( \\\"<tableNm>\\\" )\n"
    "  discard ( )\n"
    "  EC_NOT_A_TABLE false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a table                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": name::checkIsValidTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  folder[].checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm word::isKnown not if discard EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "  sTableNm name::checkIsTable not if path[].discardTableFolder false exit then\n"
    "  //sTableNm tableInUse if path[].discardTableFolder EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // pop table folder\n"
    "  path[].discardTableFolder\n"
    "\n"
    "  // assert in tables\n"
    "  folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable table folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveTable ( \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  params| sTableNm |\n"
    "\n"
    "  // check in tables folder\n"
    "  folder[].checkInTables not if false exit then\n"
    "\n"
    "  // check if tableNm is a word in tables folder\n"
    "  sTableNm word::isKnown not if discard EC_NO_SUCH_TABLE false exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "  sTableNm name::checkIsTable not if path[].discardTableFolder false exit then\n"
    "  //sTableNm tableInUse if path[].discardTableFolder EC_TABLE_IN_USE false exit then\n"
    "\n"
    "  // pop table folder\n"
    "  path[].discardTableFolder\n"
    "\n"
    "  // assert in tables\n"
    "  folder[].isTables assert\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tables folder under given named schema                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeTablesSubFolder ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLES FOR SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"tables\\\"     ( dic \\\"tables\\\" )\n"
    "  swap         ( \\\"tables\\\" dic )\n"
    "  :makeSubFolder   ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a tableNm folder under tables                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :makeTableDic ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING TABLE DIC \\\" swap str.cat\n"
    "     \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  folder[]\n"
    "  :makeSubFolder    ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a table using name on the stack (leaves table on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :createTable params| sTableNm |\n"
    "\n"
    "  find: \\\\table CN_TABLE sizeof_table sTableNm :createObject\n"
    "\n"
    "  compiler::current@ word.embObject table.init\n"
    "  true compiler::current@ word.embObject object.wordbody!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a table (run by all participants)                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeTable params| sTableNm |\n"
    "\n"
    "  0 0 locals| pTable pIndex |\n"
    "\n"
    "  args.tracepoint if\n"
    "    sTableNm \\\"MAKING TABLE \\\" swap str.cat\n"
    "    \\\" on NODE \\\" str.cat grid::thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make the table dictionary\n"
    "  sTableNm :makeTableDic\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // make the indexes dictionary\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "  sTableNm \\\":makeIndexesSubFolder\\\" find execute\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create the table\n"
    "  sTableNm :createTable ( ^table ) discard\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "  // return table pointer\n"
    "  pTable\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a table folder                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeTable params| sTableNm |\n"
    "\n"
    "  0 locals| pTable |\n"
    "\n"
    "//\\\"A\\\" . symbols\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // move to table folder\n"
    "  sTableNm path[].pushTableFolder assert\n"
    "\n"
    "//\\\"B\\\" . symbols\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables/t\n"
    "\n"
    "  // truncate the table\n"
    "  sTableNm find execute to pTable\n"
    "  args.partitionsPerNode 0\n"
    "  do\n"
    "    I pTable table.truncate\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // forget the words in the indexes folder\n"
    "  \\\"indexes\\\" find execute folder.forgetAllWords\n"
    "//\\\"C1\\\" . symbols\n"
    "\n"
    "  // forget the indexes folder itself\n"
    "  \\\"indexes\\\" folder::remove\n"
    "//\\\"C2\\\" . symbols\n"
    "\n"
    "  // forget the partitions folder itself\n"
    "  \\\"partitions\\\" folder::remove\n"
    "//\\\"C3\\\" . symbols\n"
    "\n"
    "  // forget the table folder itself\n"
    "  sTableNm folder::remove\n"
    "//\\\"C4\\\" . symbols\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // pop table\n"
    "  path[].discardTableFolder\n"
    "\n"
    "//\\\"D\\\" . symbols\n"
    "  // path: /tenants/boray/catalogs/rapidsse/schemas/public/tables\n"
    "\n"
    "  sTableNm folder::remove\n"
    "\n"
    "//\\\"E\\\" . symbols\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT db_table.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


