  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job__compiler.sen

  sFileContents =
    "\""
    "\\\"munged job__compiler.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job__compiler.sen -- Job Compiler                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job__compiler.sen\\\" .verbose\n"
    "    \n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test if the job is a generic job                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isGenericJob params| pWord |\n"
    "\n"
    "  pWord word.TagSet@ locals| pWordTagSet |\n"
    "\n"
    "  \\\"<jobKind>\\\" pWordTagSet tagSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_GENERIC\n"
    "  == if\n"
    "    // \\\"job::isGenericJob - job is a generic job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isGenericJob - job is not a generic job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isLocalJob params| pWord |\n"
    "\n"
    "  pWord word.TagSet@ locals| pWordTagSet |\n"
    "\n"
    "  \\\"<jobKind>\\\" pWordTagSet tagSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_LOCAL\n"
    "  == if\n"
    "    // \\\"job::isLocalJob - job is a local job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isLocalJob - job is not a local job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isDistJob params| pWord |\n"
    "\n"
    "  pWord word.TagSet@ locals| pWordTagSet |\n"
    "\n"
    " \\\"<jobKind>\\\" pWordTagSet tagSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_DIST2PC\n"
    "  == if\n"
    "    // \\\"job::isDistJob - job is a distributed job\\\" .\n"
    "    true\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isDistJob - job is not a distributed job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": job::isServiceCmd params| pWord |\n"
    "\n"
    "  pWord word.TagSet@ locals| pWordTagSet |\n"
    "\n"
    "  \\\"<cmdKind>\\\" pWordTagSet tagSet.getInt\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  JK_DIST2PC\n"
    "  == if\n"
    "   // \\\"job::isDistJob - job is a distributed job\\\" .\n"
    "   true\n"
    "   exit\n"
    "  then\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // \\\"job::isDistJob - job is not a distributed job\\\" .\n"
    "  false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seedExists? params| pWord sSuffix |\n"
    "\n"
    "  pWord word.name_trunc sSuffix str.cat\n"
    "    find if true else false then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*                                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seedEnameAdd params| pWord sDefaultSeed sSuffix sSeedEname |\n"
    "\n"
    "  pWord word.TagSet@ locals| pWordTagSet |\n"
    "\n"
    "  sSuffix pWord seedExists?\n"
    "    if pWord word.name_trunc else sDefaultSeed then\n"
    "    sSuffix str.cat locals| pWordName |\n"
    "\n"
    "  sSeedEname pWordName pWordTagSet tagSet.insertStr\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a distributed job                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::tagSet_dist params| pWord |\n"
    "\n"
    "  \\\"<SeedReq>\\\" \\\"_req\\\" \\\"defaultSeedDist\\\" pWord seedEnameAdd\n"
    "\n"
    "  \\\"<SeedRcv>\\\" \\\"_beg\\\" \\\"defaultSeedDist\\\" pWord seedEnameAdd\n"
    "\n"
    "  \\\"<SeedExe>\\\" \\\"_exe\\\" \\\"defaultSeedDist\\\" pWord seedEnameAdd\n"
    "\n"
    "  \\\"<SeedEnd>\\\" \\\"_end\\\" \\\"defaultSeedDist\\\" pWord seedEnameAdd\n"
    "\n"
    "  \\\"<SeedCan>\\\" \\\"_can\\\" \\\"defaultSeedDist\\\" pWord seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a local job                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::tagSet_local params| pWord |\n"
    "\n"
    "  \\\"<SeedReq>\\\" \\\"_req\\\" \\\"defaultSeedLocal\\\" pWord seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add default seeds for a generic job                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::tagSet_generic params| pWord |\n"
    "\n"
    "  \\\"<SeedReq>\\\" \\\"_run\\\" \\\"defaultSeedLocal\\\" pWord seedEnameAdd\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::addDefaultTags params| pWord |\n"
    "\n"
    "  pWord word.tagSet@ locals| pWordTagSet |\n"
    "\n"
    "  // test and add default for: command kind\n"
    "  \\\"<cmdKind>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<cmdKind>\\\" \\\"CK_COMMAND\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    "\n"
    "  // test and add default for: ddl lock\n"
    "  \\\"<ddlLock>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<ddlLock>\\\" \\\"DL_NONE\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    "\n"
    "  // test and add default for: job desc\n"
    "  \\\"<jobDesc>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<jobDesc>\\\" \\\"--description of job--\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    "\n"
    "  // test and add default for: job kind\n"
    "  \\\"<jobKind>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<jobKind>\\\" \\\"JK_LOCAL\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    "\n"
    "  // test and add default for:  priority\n"
    "  \\\"<priority>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<priority>\\\" \\\"PY_NORMAL\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    "\n"
    "  // test and add default for:  response kind\n"
    "  \\\"<rspKind>\\\" pWordTagSet tagSet.hasName not if\n"
    "    \\\"<rspKind>\\\" \\\"RS_NONE\\\" pWordTagSet tagSet.addTag\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::tags_forAnOp params| pWord |\n"
    "\n"
    "  pWord word.name_trunc locals| sWordNm_trunc |\n"
    "  pWord word.tagSet@    locals| pWordTagSet |\n"
    "\n"
    "  0 locals| iParams |\n"
    "\n"
    "  \\\"<liteOp>\\\" pWordTagSet tagSet.hasName if\n"
    "\n"
    "\n"
    "    sWordNm_trunc \\\"LiteOP: %v\\\" .printf\n"
    "\n"
    "    \\\"/liteOp/\\\" sWordNm_trunc __liteOp_PulseMarker str.replace >interpret\n"
    "    \\\"/liteOp/\\\" sWordNm_trunc __liteOp_req         str.replace >interpret\n"
    "\n"
    "    // add procedure depending on no of parameters\n"
    "    \\\"<params>\\\" pWordTagSet tagSet.hasName assert\n"
    "    \\\"<params>\\\" pWordTagSet tagSet.getStr >int to iParams\n"
    "    iParams 2 == if\n"
    "      \\\"/liteOp/\\\" sWordNm_trunc __liteOp_procedure2 str.replace procedure::add\n"
    "    else\n"
    "      iParams 1 == if\n"
    "        \\\"/liteOp/\\\" sWordNm_trunc __liteOp_procedure1 str.replace procedure::add\n"
    "      else\n"
    "       iParams 0 == assert\n"
    "       \\\"/liteOp/\\\" sWordNm_trunc __liteOp_procedure0 str.replace procedure::add\n"
    "      then\n"
    "    then\n"
    "\n"
    "\n"
    "  else\n"
    "  \\\"<localLiteOp>\\\" pWordTagSet tagSet.hasName if\n"
    "\n"
    "\n"
    "    sWordNm_trunc \\\"LocalLiteOP: %v\\\" .printf\n"
    "\n"
    "    \\\"/localLiteOp/\\\" sWordNm_trunc __localLiteOp_PulseMarker str.replace >interpret\n"
    "\n"
    "    \\\"/localLiteOp/\\\" sWordNm_trunc __localLiteOp_req         str.replace >interpret\n"
    "\n"
    "    // add procedure depending on no of parameters\n"
    "    \\\"<params>\\\" pWordTagSet tagSet.hasName assert\n"
    "    \\\"<params>\\\" pWordTagSet tagSet.getStr >int to iParams\n"
    "    iParams 2 == if\n"
    "      \\\"/localLiteOp/\\\" sWordNm_trunc __localLiteOp_procedure2   str.replace procedure::add\n"
    "    else\n"
    "    iParams 1 == if\n"
    "        \\\"/localLiteOp/\\\" sWordNm_trunc __localLiteOp_procedure1   str.replace procedure::add\n"
    "    else\n"
    "      iParams 0 == assert\n"
    "      \\\"/localLiteOp/\\\" sWordNm_trunc __localLiteOp_procedure0   str.replace procedure::add\n"
    "    then\n"
    "\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  then\n"
    "\n"
    "  pWord fillOut::tagSet_local\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* populate the JobInfo ename-set with the names of the seeds for the job     */\n"
    "/* being compiled.  Use default seeds where appropropriate                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fillOut::tagSet_ofInfoWord params| pWord |\n"
    "\n"
    "  pWord fillOut::addDefaultTags\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  pWord job::isgenericJob if\n"
    "    pWord fillOut::tagSet_generic\n"
    "  else\n"
    "  pWord job::isDistJob if\n"
    "    pWord fillOut::tagSet_dist\n"
    "  else\n"
    "    pWord fillOut::tags_forAnOp\n"
    "  then then\n"
    "\n"
    "  // pWordTagSet tagSet.asStr .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* consume service arguments                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .consumeArgs\n"
    "\n"
    "  0 locals| nArgs |\n"
    "\n"
    "  //\\\".consumeArgs\\\" .\n"
    "\n"
    "  begin\n"
    "    input::next\n"
    "    dup \\\";&\\\" str.equal not\n"
    "  while\n"
    "    nArgs 1 + to nArgs\n"
    "  repeat\n"
    "\n"
    "  // discard the \\\";&\\\" from dstack\n"
    "  discard\n"
    "\n"
    "  nArgs\n"
    "\n"
    "  // for the moment we discard the arg vector from the data stack\n"
    "  dropN\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* generate two words, one which parses and another which spawns a service    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .generateService\n"
    "\n"
    "  // calc the name of the service\n"
    "  \\\"_\\\" compiler::current@ word.name@ str.removeSuffix locals| sServiceNm |\n"
    "\n"
    "  // calc the name of the spawner\n"
    "  sServiceNm \\\"_spawner\\\" str.cat locals| sSpawnerNm |\n"
    "\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // SPAWNER\n"
    "\n"
    "  // create a word by the spawner name\n"
    "  sSpawnerNm :create\n"
    "  compiler::current@ locals| pSpawnerWd |\n"
    "\n"
    "  // debug\n"
    "  //pSpawnerWd word.dump\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // -- encode the service spawning word -- -- -- -- -- --\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // sServiceNm encode::push \\\"++ this is service spawner for: %v\\\" encode::push POSTPONE .printf\n"
    "\n"
    "  sServiceNm encode::push POSTPONE job::spawnUniversal\n"
    "\n"
    "  POSTPONE exit\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // debug\n"
    "  //pSpawnerWd word.dump\n"
    "\n"
    "\n"
    "  //----------------------------------------------------------------------------\n"
    "  // PARSER\n"
    "\n"
    "  // create an immediate word by the service name\n"
    "\n"
    "  sServiceNm :create\n"
    "  compiler::current@ locals| pServiceWd |\n"
    "  true pServiceWd word.immediate!\n"
    "\n"
    "  // debug\n"
    "  //pServiceWd word.dump\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "  // -- encode the service parsing word  -- -- -- -- -- --\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // in : <serviceNm> add call(.printf)\n"
    "  // sServiceNm encode::push \\\"++ this is the service parser for: %v\\\" encode::push POSTPONE .printf\n"
    "\n"
    "  // in : <serviceNm> add call(.consumeArgs)\n"
    "  POSTPONE .consumeArgs\n"
    "\n"
    "  // in : <serviceNm> add code which adds call(` pSpawnerWd) in caller of service\n"
    "  pSpawnerWd encode::push POSTPONE encode::call\n"
    "\n"
    "  // in : <serviceNm> add exit\n"
    "  POSTPONE exit\n"
    "\n"
    "  // -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- -- --\n"
    "\n"
    "  // debug\n"
    "  //pServiceWd word.dump\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* the job info compiler                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": jobInfo:\n"
    "\n"
    "  0 0 0 0 locals| pWord sEname sEvalue pWordTagSet |\n"
    "\n"
    "  // create a word using next token from input source as the word name\n"
    "  input::next \\\"_info\\\" str.cat :create\n"
    "\n"
    "  compiler::current@ to pWord\n"
    "\n"
    "  // set the word kind to be jobClass\n"
    "  [ compiler::current@ encode::push ] pWord word.category!\n"
    "\n"
    "  // attach an ename set to the word being created\n"
    "  tagSet::new to pWordTagSet\n"
    "\n"
    "  pWordTagSet pWord word.TagSet!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  \\\"<jobNm>\\\" pWord word.name_trunc pWordTagSet tagSet.insertStr\n"
    "\n"
    "  // skip the \\\"{\\\" token from input source\n"
    "  input::next discard\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // parse each input token till \\\"}\\\", build ename set representing the syntax\n"
    "\n"
    "  begin\n"
    "    input::next\n"
    "    dup \\\"}\\\" str.equal not\n"
    "  while\n"
    "    to sEname\n"
    "    input::next discard\n"
    "    input::next to sEvalue\n"
    "    sEname sEvalue pWord word.TagSet@ tagSet.addTag\n"
    "  repeat\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // discard the \\\"}\\\" from dstack\n"
    "  discard\n"
    "\n"
    "  // get and discard \\\";\\\"\n"
    "  input::next discard\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // complete the ename-set\n"
    "\n"
    "  //pWordTagSet tagSet.asStr .\n"
    "\n"
    "  pWord fillOut::tagSet_ofInfoWord\n"
    "\n"
    "  //pWordTagSet tagSet.asStr .\n"
    "\n"
    "  pWord job::isServiceCmd if .generateService then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job__compiler.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of se_word.sen

  sFileContents =
    "\""
    "\\\"munged se_word.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_word.sen -- additional word related words                               */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" se_word.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ensure the word has an ename set                                           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.ensureTagSet params| pWord |\n"
    "\n"
    "  pWord word.tagSet@ not if\n"
    "    tagSet::new pWord word.tagSet!\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check for known word                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word::isKnown ( <\\\"wordNm\\\"> )\n"
    "  find\n"
    "  not if EC_NO_SUCH_WORD false exit_rt then\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return word name with any suffix removed                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.name_trunc params| pWord |\n"
    "\n"
    "  \\\"_\\\" pWord word.name@ str.removeSuffix\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* show details of given word                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": word.show params| pWord |\n"
    "\n"
    "  pWord word.name@     locals| sWordName |\n"
    "  pWord word.category@ locals| pCatg |\n"
    "  pCatg word.name@     locals| sCatgName |\n"
    "\n"
    "  sCatgName sWordName\n"
    "    \\\"Word: %24v Category: %16v\\\" .printf\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list all words in the current dictionary                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": words prompt\n"
    "\n"
    "  //folder[] dic.lastWord dup\n"
    "  dic::root dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ word.name@ .         // print the name of the word\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT se_word.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of job_Alarm.sen

  sFileContents =
    "\""
    "\\\"munged job_Alarm.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* job_Alarm.sen -- alarm job                                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" job_Alarm.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* alarm loop:                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": alarm_req ( -- )\n"
    "\n"
    "  std_entryHook\n"
    "\n"
    "  \\\"Alarm Job Started\\\" .\n"
    "\n"
    "  begin\n"
    "\n"
    "    \\\"Alarm Job\\\" .\n"
    "\n"
    "    handler::serviceSleepQueue\n"
    "\n"
    "  again\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // should never exit\n"
    "  hazard\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/***                            - Definition -                              ***/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "jobSyntax: alarm :: alarm ;\n"
    "\n"
    "jobInfo: alarm\n"
    "{\n"
    "  <jobDesc>  = \\\"--description of job--\\\"\n"
    "  \n"
    "  <jobKind>  = JK_LOCAL\n"
    "  <rspKind>  = RS_NONE\n"
    "  <ddlLock>  = DL_NONE\n"
    "  \n"
    "  //<preCheck> = bClusterStarted\n"
    "  \n"
    "  <cmdKind>  = CK_SERVICE\n"
    "}\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT job_Alarm.sen"_Stz
  ;

  vCompileMungedColon(sFileContents);


  //!- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -
  // munge of se_core.sen

  sFileContents =
    "\""
    "\\\"munged se_core.sen \\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* se_core.sen -- core words                                                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\" se_core.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add 1 to integer on stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 1+ 1 + ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* decrement integer on stack                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": 1- 1 - ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* allot n bytes of data in wsp of current word                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ALLOT\n"
    "\n"
    "  compiler::current@ word.allotObject discard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* push size of cell                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": CELL\n"
    "\n"
    "  8\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* start of code for some future word                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": DOES> immediate\n"
    " \n"
    "  // we are in the compilation of a defining word\n"
    "\n"
    "  // encode call in current defining word so when this current word is\n"
    "  //   executed its sets the routine entry point for some future word\n"
    "  FIND: does_rt ENCODE::CALL\n"
    "\n"
    "  // encode an exit in current defining word\n"
    "  FIND: exit_rt ENCODE::CALL\n"
    "\n"
    "  // what gets coded in the current defining after does>\n"
    "  //   is the code for some future word, embedded in this current word here\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a new word using string on stack as name                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :CREATE ( sWordNM -- )\n"
    "\n"
    "  word::new compiler::current!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a new word using next token as name                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": CREATE:\n"
    "\n"
    "  input::read input::token :create\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a new object-word                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :CREATEOBJECT ( pCatg eClass nBytes sObjectNM -- )\n"
    "\n"
    "  :create ( pCatg eClass nBytes )\n"
    "\n"
    "  WK_EMBOBJECT compiler::current@ word.kind! ( pCatg eClass nBytes )\n"
    "\n"
    "  allot ( pCatg eClass )\n"
    "\n"
    "  compiler::current@ word.embObject object.class! ( pCatg )\n"
    "\n"
    "  compiler::current@ word.category! ( )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  compiler::current@ word.embObject object.magic!\n"
    "  //true compiler::current@ word.embObject object.wordbody!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  compiler::current@\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a new C++ object-word                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :CREATECPPOBJECT ( pCatg pObject sObjectNM -- )\n"
    "\n"
    "  :create ( pCatg pObject )\n"
    "\n"
    "  WK_CPPOBJECT compiler::current@ word.kind! ( pCatg pObject )\n"
    "\n"
    "  compiler::current@ word.object! ( pCatg )\n"
    "\n"
    "  compiler::current@ word.category! ( )\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  compiler::current@\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find a word using its name                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": FIND\n"
    "\n"
    "  word::find\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* locate a word using a fip                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": LOCATE\n"
    "\n"
    "  word::locate\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* begin a loop                                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": BEGIN immediate\n"
    "\n"
    "  HERE // push address of last cell of word\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* do a loop                                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": DO immediate\n"
    "\n"
    "  POSTPONE 2>R // encode 2>r into future word\n"
    "  HERE true    // push address of last cell & simple do\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ?do a loop                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ?DO immediate\n"
    "\n"
    "  POSTPONE 2>R   // encode 2>r into future word\n"
    "  POSTPONE AHEAD\n"
    "  false          // push address of last cell & simple do\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* unloop by dropping limit and index off rstack                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": UNLOOP immediate\n"
    "\n"
    "  POSTPONE rdiscard\n"
    "  POSTPONE rdiscard\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* iterate a loop                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ITERATE immediate\n"
    "\n"
    "  POSTPONE 2>R // encode 2>r into future word\n"
    "  POSTPONE AHEAD\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define a constant                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ,_ALT\n"
    "\n"
    "  HERE ! CELL ALLOT\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define a constant                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": CONSTANT\n"
    "\n"
    "  CREATE:          // create a word using the next token in the input stream\n"
    "  encode::push     // encode a push value of the value currently on the stack\n"
    "  POSTPONE exit_rt // encode an exit into the created word\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* resolve IF supplying alternate execution                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ELSE immediate ( orig1 -- orig2 / -- )\n"
    "\n"
    "  POSTPONE AHEAD // unconditional forward branch orig2\n"
    "  1 CS-ROLL      // put orig1 back on top\n"
    "  POSTPONE THEN  // resolve forward branch from orig1\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* conditional exit from loops                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": WHILE immediate ( dest -- orig dest / flag -- )\n"
    "\n"
    "  POSTPONE IF // conditional forward branch\n"
    "  1 CS-ROLL   // keep dest on top\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* resolve a single WHILE and jump to BEGIN                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": REPEAT immediate ( orig dest -- orig dest / flag -- )\n"
    "\n"
    "  POSTPONE AGAIN // unconditional backward branch to dest\n"
    "  POSTPONE THEN  // resolve forward branch from orig\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* initialise OFs counter                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "0 CONSTANT CASE\n"
    "true find: CASE word.immediate!\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* OF block                                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": OF immediate\n"
    "\n"
    "  1+   // inc number of OFs\n"
    "  >R   // save OFs counter\n"
    "\n"
    "  POSTPONE OVER     // copy case value\n"
    "  POSTPONE ==       // test case value against of value\n"
    "  POSTPONE IF       // add conditional block (with orig on control stack)\n"
    "  POSTPONE DISCARD  // discard case value within conditional block\n"
    "\n"
    "  R> // restore OFs counter\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ENDOF block                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ENDOF immediate\n"
    "\n"
    "  >R            // save OFs counter\n"
    "  POSTPONE ELSE // add conditional block (with orig2 on control stack)\n"
    "  R>            // restore OFs counter\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* ENDCASE block                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ENDCASE immediate\n"
    "\n"
    "  POSTPONE DISCARD // discard case value\n"
    "\n"
    "  0 ?DO            // resolve all forward ENDOF branches\n"
    "    POSTPONE THEN\n"
    "  LOOP\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* mark as executable by prompt                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": PROMPT immediate\n"
    "\n"
    "  true compiler::current@ word.prompt!\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget word using next token as word name                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": FORGET\n"
    "\n"
    "  input::read input::token word::find dup if\n"
    "    word::delete\n"
    "  else\n"
    "    discard\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* EXIT (optionally invoking exit hook)                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": EXIT immediate\n"
    "\n"
    "  compiler::current@ word.exitHook@ word::find dup if\n"
    "    encode::call\n"
    "  else\n"
    "    discard\n"
    "  then\n"
    "\n"
    "  POSTPONE exit_rt\n"
    " ;\n"
    "\n"
    ": eg_hook\n"
    "   \\\"eg_hook\\\" .\n"
    " ;\n"
    "\n"
    ": set_hook immediate\n"
    "\n"
    "  \\\"eg_hook\\\"\n"
    "  compiler::current@\n"
    "  word.exitHook!\n"
    " ;\n"
    "\n"
    ": exit_test prompt\n"
    "\n"
    "  set_hook\n"
    "  //[ \\\"eg_hook\\\" compiler::current@ word.exitHook! ]\n"
    "\n"
    "  1 if\n"
    "    \\\"exit with hook\\\" . exit\n"
    "  else\n"
    "    \\\"normal exit\\\"    . exit_rt\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* increment integer variable                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ++ dup @ 1+ swap ! ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* decrement integer variable                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": -- dup @ 1- swap ! ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define a constant (using name on stack)                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :constant\n"
    "\n"
    "  // create a word using the string on top of the stack\n"
    "  :create\n"
    "\n"
    "  // encode a push value of the value currently on the stack\n"
    "  encode::push\n"
    "\n"
    "  // encode a push value of the value currently on the stack\n"
    "  POSTPONE exit_rt\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forget named word                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :forget ( <\\\"wordNm\\\"> )\n"
    "\n"
    "  find dup not if discard exit_rt then\n"
    "\n"
    "  word::delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* discard all values on stack except topmost                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": nipAll ( ... top -- top )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit_rt then\n"
    "\n"
    "  // save topmost\n"
    "  >r\n"
    "\n"
    "  // discard everything else\n"
    "  begin\n"
    "    depth while\n"
    "      discard\n"
    "  repeat\n"
    "\n"
    "  // restore topmost\n"
    "  r>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* discard n values from stack                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dropN ( ... #values -- )\n"
    "\n"
    "  // handle expty stack case\n"
    "  depth not if exit_rt then\n"
    "\n"
    "  // discard n values\n"
    "  0 ?do\n"
    "    discard\n"
    "  loop\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get nested Word$$<n>                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": Word$$    compiler::nested@ ;\n"
    ": Word$$0 0 compiler::nested@ ;\n"
    ": Word$$1 1 compiler::nested@ ;\n"
    ": Word$$2 2 compiler::nested@ ;\n"
    ": Word$$3 3 compiler::nested@ ;\n"
    ": Word$$4 4 compiler::nested@ ;\n"
    ": Word$$5 5 compiler::nested@ ;\n"
    ": Word$$6 6 compiler::nested@ ;\n"
    ": Word$$7 7 compiler::nested@ ;\n"
    ": Word$$8 8 compiler::nested@ ;\n"
    ": Word$$9 9 compiler::nested@ ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* start compiling nested word                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :NestedWord\n"
    "\n"
    "  word::new dup compiler::current! compiler::nested!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end compiling nested word                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ;NestedWord\n"
    "\n"
    "  POSTPONE exit_rt\n"
    "\n"
    "  0 compiler::nested@ compiler::current!\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump the return stack                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rstk_w\n"
    "\n"
    "  \\\"return stack\\\" .\n"
    "  rdepth dup not if discard exit_rt then\n"
    "  0 do\n"
    "    I 2 + rpick\n"
    "    dup .put\n"
    "    \\\" \\\".put\n"
    "    locate\n"
    "    dup if .put else discard then\n"
    "    .\\\\n\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* interpret string on stack                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >interpret\n"
    "\n"
    "   input::push\n"
    "   input::text!\n"
    "   input::senTokens\n"
    "   input::useBegin\n"
    "\n"
    "   interpret\n"
    " \n"
    "   input::useEnd\n"
    "   input::pop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* test type of top stack value                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": isType ( CN_ -- bool )\n"
    "\n"
    "  // false if stack empty\n"
    "  depth 2 >= not if discard false exit_rt then\n"
    "\n"
    "  // no more if not indirect\n"
    "  1 stack.class ==\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* formatted print     https://en.wikipedia.org/wiki/Printf_format_string     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": .printf\n"
    "\n"
    "  str.format .\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* include a sub dir of sen files                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": include-subdir\n"
    "\n"
    "  params| sSubDir |\n"
    "\n"
    "  0 locals| sFilePath |\n"
    "\n"
    "  input::push\n"
    "\n"
    "  args.senDir sSubDir str.cat dup\n"
    "\n"
    "  \\\"Would include .sen files from sub-dir %v\\\" .printf\n"
    "\n"
    "  dir::new locals| pSubDir |\n"
    "\n"
    "  pSubDir dir.open if\n"
    "\n"
    "    begin\n"
    "      pSubDir dir.read\n"
    "    while\n"
    "      pSubDir dir.entryName \\\"Entry %v\\\" .printf\n"
    "\n"
    "      4 pSubDir dir.entryName str.right \\\".sen\\\" str.equal if\n"
    "        pSubDir dir.entryName \\\"Would parse %v\\\" .printf\n"
    "\n"
    "        args.senDir sSubDir str.cat\n"
    "          \\\"/\\\" str.cat\n"
    "          pSubDir dir.entryName str.cat\n"
    "          to sFilePath\n"
    "        sFilePath \\\"Would open %v\\\" .printf\n"
    "\n"
    "        sFilePath\n"
    "          input::open\n"
    "          input::useBegin\n"
    "          interpret\n"
    "          input::useEnd\n"
    "          input::inspect\n"
    "          input::close\n"
    "\n"
    "      then\n"
    "\n"
    "    repeat\n"
    "\n"
    "    pSubDir dir.close\n"
    "  then\n"
    "\n"
    "  pSubDir dir.delete\n"
    "\n"
    "  input::pop\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* stack should have zero values                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": trap::stackDepthZero\n"
    "\n"
    "  depth 0 == if exit_rt then\n"
    "\n"
    "  task[] task.name@ \\\"Stack of task %v has grown\\\" .printf\n"
    "\n"
    "  debug::trap\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* snooze briefly                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": snooze ( -- )\n"
    "\n"
    "  C_1M thread::sleepNsec\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put task into infinite snooze loop                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": snoozeLoop\n"
    "\n"
    "  begin\n"
    "    \\\"snoozing...\\\" . snooze task::yield\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* hello world                                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": helloWorld prompt\n"
    "\n"
    "  \\\"Hello World!\\\" .\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT se_core.sen"_Stz
  ;

